// TestSpecPinsS8Hold is the guard on the real spec for this card's rows: every
// normative sentence of section 8 and every later section carries a row id,
// every row is pinned in every port it owes or owed by name, and every pin
// resolves.
func TestSpecPinsS8Hold(t *testing.T) {
	t.Parallel()
	root := repoRoot(t)
	doc, findings := checkSpecPins(specPinsInput{fsys: os.DirFS(root), spec: "docs/SPEC-TABLES.md", roadmap: "docs/roadmap.sexp", pins: specPinRegistry})
	for _, f := range findings {
		t.Error(f)
	}
	rows := 0
	for id := range doc.Rows {
		if strings.HasPrefix(id, "T8.") {
			rows++
		}
	}
	if rows < 263 {
		t.Fatalf("the guard read %d section-8 rows; the pin registry names 263", rows)
	}
}

// TestSpecPinsS8Plant plants a new unmarked rule in the pinned section 8.2 and
// requires the guard to go red on it; the real spec, with the plant out, must
// stay green. A guard that cannot go red proves nothing.
func TestSpecPinsS8Plant(t *testing.T) {
	t.Parallel()
	root := repoRoot(t)
	base := os.DirFS(root)
	spec, err := fs.ReadFile(base, "docs/SPEC-TABLES.md")
	if err != nil {
		t.Fatal(err)
	}
	const heading = "### 8.2 The type view: every type, on the side\n"
	if !strings.Contains(string(spec), heading) {
		t.Fatalf("the spec no longer carries %q; the plant needs a live pinned section", heading)
	}
	const rule = "A view must not invent a type that the declaration did not write.\n"
	planted := strings.Replace(string(spec), heading, heading+"\n"+rule, 1)
	fsys := overlayFS{FS: base, over: map[string][]byte{"docs/SPEC-TABLES.md": []byte(planted)}}
	_, got := checkSpecPins(specPinsInput{fsys: fsys, spec: "docs/SPEC-TABLES.md", roadmap: "docs/roadmap.sexp", pins: specPinRegistry})
	all := strings.Join(got, "\n")
	if !strings.Contains(all, `normative sentence without a row id (section "8.2 The type view: every type, on the side")`) {
		t.Fatalf("planted an unmarked rule in section 8.2; the guard stayed green:\n%s", all)
	}
	_, clean := checkSpecPins(specPinsInput{fsys: base, spec: "docs/SPEC-TABLES.md", roadmap: "docs/roadmap.sexp", pins: specPinRegistry})
	if strings.Contains(strings.Join(clean, "\n"), "normative sentence without a row id") {
		t.Fatalf("the plant is out but the guard still reports an unmarked rule:\n%s", strings.Join(clean, "\n"))
	}
}
